import{_ as a,o as i,c as t,a2 as o}from"./chunks/framework.BXzK3EA4.js";const h=JSON.parse('{"title":"Language Server","description":"","frontmatter":{},"headers":[],"relativePath":"tooling/lsp.md","filePath":"tooling/lsp.md"}'),n={name:"tooling/lsp.md"};function r(s,e,l,d,c,m){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="language-server" tabindex="-1">Language Server <a class="header-anchor" href="#language-server" aria-label="Permalink to &quot;Language Server&quot;">​</a></h1><p>The <code>kolt-lsp</code> binary implements the Language Server Protocol (LSP), communicating over standard I/O (<code>stdio</code>) with editors such as VS Code, Neovim, and Helix.</p><p>It provides real-time diagnostics, semantic tokens, workspace scanning, and an incremental memoized analysis cache.</p><hr><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><h3 id="autocompletion" tabindex="-1">Autocompletion <a class="header-anchor" href="#autocompletion" aria-label="Permalink to &quot;Autocompletion&quot;">​</a></h3><p>Triggered on typing, member access (<code>.</code>), and directives (<code>@</code>):</p><ul><li>Keywords, variables, and local symbols.</li><li>Named and positional function parameters with snippet insertion.</li><li>Object methods, class fields, and native prototype methods with inferred element types.</li><li>Interfaces, classes, enums, and enum members.</li><li>Module import paths with automatic import insertion suggestions.</li></ul><h3 id="hover-information" tabindex="-1">Hover Information <a class="header-anchor" href="#hover-information" aria-label="Permalink to &quot;Hover Information&quot;">​</a></h3><ul><li>Inferred and static types with active type narrowing.</li><li>Doc comments and parameter documentation.</li><li>Interface definitions and structural contracts.</li></ul><h3 id="navigation-refactoring" tabindex="-1">Navigation &amp; Refactoring <a class="header-anchor" href="#navigation-refactoring" aria-label="Permalink to &quot;Navigation &amp; Refactoring&quot;">​</a></h3><ul><li><strong>Go to Definition</strong>: Jumps directly to symbol declarations with exact source ranges, including embedded standard library sources.</li><li><strong>Find References</strong>: Locates usages across the entire workspace.</li><li><strong>Rename Symbol</strong>: Project-wide renaming that respects exports, scopes, and shadowing while protecting standard library symbols.</li><li><strong>Document Highlights &amp; Symbols</strong>: Outlines classes, methods, and definitions for quick navigation.</li></ul><h3 id="diagnostics-code-actions" tabindex="-1">Diagnostics &amp; Code Actions <a class="header-anchor" href="#diagnostics-code-actions" aria-label="Permalink to &quot;Diagnostics &amp; Code Actions&quot;">​</a></h3><ul><li>Debounced compiler diagnostics with precise spans and related information.</li><li>Automated quick fixes: <ul><li>Inserting missing <code>try</code> keywords on unhandled throwing expressions.</li><li>Auto-importing unresolved module identifiers.</li></ul></li></ul><h3 id="code-formatting" tabindex="-1">Code Formatting <a class="header-anchor" href="#code-formatting" aria-label="Permalink to &quot;Code Formatting&quot;">​</a></h3><p>Reuses the native AST formatter (<code>kolt fmt</code>):</p><ul><li>Consistent 4-space indentation.</li><li>Preserved comments and blank lines.</li><li>Aligned method chains and match arm bodies.</li></ul><hr><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><h3 id="inlay-hints" tabindex="-1">Inlay Hints <a class="header-anchor" href="#inlay-hints" aria-label="Permalink to &quot;Inlay Hints&quot;">​</a></h3><p>Inlay hints display inferred types for <code>let</code> and <code>const</code> bindings, as well as parameter types for anonymous functions.</p><p>Inlay hints are disabled by default and can be enabled via:</p><ul><li>Editor configuration: <code>initializationOptions.inlayHints: true</code></li><li>Environment variable: <code>KOLT_INLAY_HINTS=1</code></li></ul>',23)])])}const p=a(n,[["render",r]]);export{h as __pageData,p as default};
